return $input.all().map(item => {
  const data = item.json;

  const notes = String(data.meeting_notes ?? '');

  if (!notes.trim()) {
    throw new Error('Original meeting notes are missing.');
  }

  // Use only the original notes to create a stable identity.
  let hash = 2166136261;

  for (let i = 0; i < notes.length; i++) {
    hash ^= notes.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  const meetingId = String(
    (hash >>> 0) % 100000000
  ).padStart(8, '0');

  return {
    json: {
      ...data,
      meeting_id: meetingId
    }
  };
});
